namespace Vnecoms\VendorsCms\Model\ResourceModel\Block;

/**
 * CMS Block Collection.
 */
class Collection extends \Magento\Framework\Model\ResourceModel\Db\Collection\AbstractCollection
{
    /**
     * @var string
     */
    protected $_idFieldName = 'block_id';

    /** @var \Vnecoms\Vendors\Model\Session  */
    protected $vendorSession;

    /**
     * Collection constructor.
     *
     * @param \Magento\Framework\Data\Collection\EntityFactoryInterface    $entityFactory
     * @param \Psr\Log\LoggerInterface                                     $logger
     * @param \Magento\Framework\Data\Collection\Db\FetchStrategyInterface $fetchStrategy
     * @param \Magento\Framework\Event\ManagerInterface                    $eventManager
     * @param \Magento\Framework\DB\Adapter\AdapterInterface|null          $connection
     * @param \Magento\Framework\Model\ResourceModel\Db\AbstractDb|null    $resource
     */
    public function __construct(
        \Magento\Framework\Data\Collection\EntityFactoryInterface $entityFactory,
        \Psr\Log\LoggerInterface $logger,
        \Magento\Framework\Data\Collection\Db\FetchStrategyInterface $fetchStrategy,
        \Magento\Framework\Event\ManagerInterface $eventManager,
        \Magento\Framework\DB\Adapter\AdapterInterface $connection = null,
        \Magento\Framework\Model\ResourceModel\Db\AbstractDb $resource = null
    ) {
        parent::__construct($entityFactory, $logger, $fetchStrategy, $eventManager, $connection, $resource);
    }

    /**
     * Define resource model.
     */
    protected function _construct()
    {
        $this->_init('Vnecoms\VendorsCms\Model\Block', 'Vnecoms\VendorsCms\Model\ResourceModel\Block');
        //$this->_map['fields']['store'] = 'store_table.store_id';
        $this->_map['fields']['block_id'] = 'main_table.block_id';
    }

    /**
     * @return $this|void
     */
    protected function _initSelect()
    {
        if ($this->vendorSession instanceof \Vnecoms\Vendors\Model\Session) {
            $vendor = $this->vendorSession->getVendor();
        } else {
            $vendor = \Magento\Framework\App\ObjectManager::getInstance()->create('\Vnecoms\Vendors\Model\Session')->getVendor();
        }

        $this->addVendorFilter($vendor);

        return parent::_initSelect(); // TODO: Change the autogenerated stub
    }

    /**
     * Returns pairs identifier - title.
     *
     * @return array
     */
    public function toOptionArray()
    {
        return $this->_toOptionArray('identifier', 'title');
    }

    /**
     * @param \Vnecoms\Vendors\Model\Vendor $vendor
     *
     * @return $this
     */
    public function addVendorFilter($vendor)
    {
        $this->addFieldToFilter('vendor_id', ['eq' => $vendor->getId()]);

        return $this;
    }
}
